    qualname = getattr(obj, '__qualname__', '')
    cls_path, _, _ = qualname.rpartition('.')
    if cls_path:
        try:
            if '.' in cls_path:
                import importlib
                import functools

                mod = importlib.import_module(obj.__module__)
                mod_path = cls_path.split('.')
                cls = functools.reduce(getattr, mod_path, mod)
            else:
                cls = obj.__globals__[cls_path]
        except Exception:
            cls_is_owner = False
        else:
            cls_is_owner = (cls and hasattr(cls, name) and  # type: ignore
                            name in cls.__dict__)
    else:
        cls_is_owner = False

    # Additional check for decorated methods
    if not cls_is_owner and hasattr(obj, '__wrapped__'):
        wrapped_obj = obj.__wrapped__
        qualname = getattr(wrapped_obj, '__qualname__', '')
        cls_path, _, _ = qualname.rpartition('.')
        if cls_path:
            try:
                if '.' in cls_path:
                    mod = importlib.import_module(wrapped_obj.__module__)
                    mod_path = cls_path.split('.')
                    cls = functools.reduce(getattr, mod_path, mod)
                else:
                    cls = wrapped_obj.__globals__[cls_path]
            except Exception:
                cls_is_owner = False
            else:
                cls_is_owner = (cls and hasattr(cls, name) and  # type: ignore
                                name in cls.__dict__)
```

This fix checks if the method is decorated and uses the `__wrapped__` attribute to find the original method, ensuring that the `__init__` method is correctly identified and included in the documentation.

